def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = max(range(10), key=lambda x: sum(row.count(x) for row in grid))
    # The bottom row contains the five-cell pattern; each isolated 6 marks
    # the location of its leading 8 in a target row.
    row = max(range(h), key=lambda r: sum(v != bg for v in grid[r]))
    cells = [(c, grid[row][c]) for c in range(w) if grid[row][c] != bg]
    left = min(c for c, v in cells)
    pattern = [grid[row][c] for c in range(left, max(c for c, v in cells)+1)]
    for r in range(h):
        if r == row:
            continue
        for c, v in enumerate(grid[r]):
            if v == 6:
                for k, p in enumerate(pattern):
                    target = c + k - 2
                    if 0 <= target < w:
                        out[r][target] = p
    return out

